def list_docs() -> list[dict]:
    return [{"key": k, "title": v["title"], "filename": v["filename"]} for k, v in DOCS.items()]


def render_doc(key: str, company: str, email: str) -> tuple[str, str]:
    """Returns (filename, content)."""
    d = DOCS[key]
    content = d["body"].format(company=company, email=email, date=time.strftime("%Y-%m-%d"), disclaimer=DISCLAIMER)
    return d["filename"], content


def generate_all(company: str, email: str, out_dir: str, only: list[str] | None = None,
                 pdf: bool = False) -> list[str]:
    os.makedirs(out_dir, exist_ok=True)
    paths = []
    for key in (only or list(DOCS.keys())):
        filename, content = render_doc(key, company, email)
        p = os.path.join(out_dir, filename)
        with open(p, "w") as f:
            f.write(content)
        paths.append(p)
        if pdf:
            from .pdf import markdown_to_pdf
            pp = os.path.splitext(p)[0] + ".pdf"
            markdown_to_pdf(content, pp, title=f"{DOCS[key]['title']} — {company}")
            paths.append(pp)
    return paths
